    GraphPathImpl<V, E> path = new GraphPathImpl<>(graph, null, 0.0);
    List<E> edgeList = new ArrayList<>(tour);
    for (E edge : edgeList) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        path.add(source, edge, graph.getEdgeWeight(edge));
    }
    // Assuming the tour forms a closed loop, add the last edge to point back to the start
    if (!edgeList.isEmpty()) {
        E lastEdge = edgeList.get(edgeList.size() - 1);
        V lastSource = graph.getEdgeSource(lastEdge);
        V lastTarget = graph.getEdgeTarget(lastEdge);
        V startVertex = graph.getEdgeSource(edgeList.get(0));
        if (startVertex.equals(lastTarget)) {
            path.add(lastTarget, lastEdge, graph.getEdgeWeight(lastEdge));
        } else if (startVertex.equals(lastSource)) {
            path.add(lastSource, lastEdge, graph.getEdgeWeight(lastEdge));
        }
    }
    return path;
}

